count-prefix-and-suffix-pairs-i:
class Solution:
    def countPrefixSuffixPairs(self, words: List[str]) -> int:
        ans = 0
        for i in range(len(words)):
            for j in range(i+1, len(words)):
                if words[j].startswith(words[i]) and words[j].endswith(words[i]):
                    ans += 1
        return ans

count-pairs-of-similar-strings:
class Solution:
    def similarPairs(self, words: List[str]) -> int:
        from collections import Counter
        c = Counter(''.join(sorted(set(w))) for w in words)
        return sum(v*(v-1)//2 for v in c.values())

number-of-distinct-averages:
class Solution:
    def distinctAverages(self, nums: List[int]) -> int:
        nums.sort()
        s = set()
        l, r = 0, len(nums)-1
        while l < r:
            s.add((nums[l]+nums[r])/2)
            l += 1; r -= 1
        return len(s)

largest-positive-integer-that-exists-wit:
class Solution:
    def findMaxK(self, nums: List[int]) -> int:
        seen = set(nums)
        ans = -1
        for x in nums:
            if x > ans and -x in seen:
                ans = x
        return ans

find-subarrays-with-equal-sum:
class Solution:
    def findSubarrays(self, nums: List[int]) -> bool:
        seen = set()
        for i in range(len(nums)-1):
            s = nums[i]+nums[i+1]
            if s in seen: return True
            seen.add(s)
        return False

split-strings-by-separator:
class Solution:
    def splitWordsBySeparator(self, words: List[str], separator: str) -> List[str]:
        res = []
        for w in words:
            for part in w.split(separator):
                if part: res.append(part)
        return res

sum-of-squares-of-special-elements:
class Solution:
    def sumOfSquares(self, nums: List[int]) -> int:
        n = len(nums)
        return sum(nums[i]**2 for i in range(n) if n % (i+1) == 0)

neither-minimum-nor-maximum:
class Solution:
    def findNonMinOrMax(self, nums: List[int]) -> int:
        mn, mx = min(nums), max(nums)
        for x in nums:
            if x != mn and x != mx: return x
        return -1

number-of-beautiful-pairs:
class Solution:
    def countBeautifulPairs(self, nums: List[int]) -> int:
        ans = 0
        for i in range(len(nums)):
            for j in range(i+1, len(nums)):
                first = int(str(nums[i])[0])
                last = nums[j] % 10
                if __import__('math').gcd(first, last) == 1:
                    ans += 1
        return ans

divisible-and-non-divisible-sums-differe:
class Solution:
    def differenceOfSums(self, n: int, m: int) -> int:
        num1 = sum(x for x in range(1, n+1) if x % m != 0)
        num2 = sum(x for x in range(1, n+1) if x % m == 0)
        return num1 - num2

find-the-k-or-of-an-array:
class Solution:
    def findKOr(self, nums: List[int], k: int) -> int:
        ans = 0
        for b in range(32):
            cnt = sum(1 for x in nums if (x >> b) & 1)
            if cnt >= k: ans |= (1 << b)
        return ans

construct-the-rectangle:
class Solution:
    def constructRectangle(self, area: int) -> List[int]:
        import math
        for w in range(int(math.isqrt(area)), 0, -1):
            if area % w == 0:
                return [area//w, w]
        return [area, 1]

first-unique-even-element:
class Solution:
    def firstUniqueEvenElement(self, nums: List[int]) -> int:
        from collections import Counter
        c = Counter(nums)
        for x in nums:
            if x % 2 == 0 and c[x] == 1: return x
        return -1

find-first-palindromic-string-in-the-arr:
class Solution:
    def firstPalindrome(self, words: List[str]) -> str:
        for w in words:
            if w == w[::-1]: return w
        return ""

longest-nice-substring:
class Solution:
    def longestNiceSubstring(self, s: str) -> str:
        n = len(s)
        best = ""
        for i in range(n):
            for j in range(i+1, n+1):
                sub = s[i:j]
                if all(c.islower() and c.upper() in sub or c.isupper() and c.lower() in sub for c in sub):
                    if len(sub) > len(best): best = sub
        return best

minimum-difference-between-highest-and-l:
class Solution:
    def minimumDifference(self, nums: List[int], k: int) -> int:
        nums.sort()
        ans = float('inf')
        for i in range(len(nums)-k+1):
            ans = min(ans, nums[i+k-1]-nums[i])
        return ans

minimum-cost-of-buying-candies-with-disc:
class Solution:
    def minimumCost(self, cost: List[int]) -> int:
        cost.sort(reverse=True)
        return sum(cost[i] for i in range(len(cost)) if i % 3 != 2)

second-largest-digit-in-a-string:
class Solution:
    def secondHighest(self, s: str) -> int:
        digs = set(int(c) for c in s if c.isdigit())
        if len(digs) < 2: return -1
        return sorted(digs)[-2]

